/**
 * Покрытия: чем земля отличается от земли.
 *
 * Это словарь, общий для всех, кто с землёй имеет дело, и собран он здесь ровно
 * потому, что раньше был разложен по трём местам в трёх ролях. Имена покрытий
 * жили в трассе, физические свойства — в шине, материалы для глаза — в сцене, и
 * ни одно из трёх не было хозяином: добавить покрытие значило вспомнить все три
 * файла и надеяться, что ничего не забыл.
 *
 * Разделение ответственности после сборки такое. Здесь — что покрытие такое:
 * насколько держит, насколько вязнет, насколько шумит, держит ли след. В шине
 * (`@gamespace/car`) — что из этого выходит в пятне контакта: кривая
 * проскальзывания, нагрев, чернота полосы. В игре — где какое покрытие лежит,
 * потому что это вопрос устройства конкретного мира, а не покрытий как таких.
 *
 * Числа не из справочника, а из того, чем эти покрытия отличаются в заезде:
 * асфальт держит, гравий держит хуже и шумит, трава почти не держит и вязнет.
 */

export type SurfaceKind = "asphalt" | "gravel" | "grass";

export interface Surface {
  /** Сцепление относительно сухого асфальта. */
  grip: number;
  /**
   * Держит ли покрытие след: 1 — асфальт, 0 — трава.
   *
   * Чёрная полоса на дороге — это не царапина, а плёнка стёртой резины,
   * оставшаяся на поверхности. Значит поверхность должна быть, во-первых,
   * сплошной, а во-вторых, твёрже резины: с гладкого асфальта плёнке некуда
   * деться, гравий её уносит вместе с камешками, а на траве мазать нечего
   * вовсе — там остаётся колея, и это совсем другое явление.
   */
  keeps: number;
  /** Сопротивление качению, доля от нормальной нагрузки. */
  roll: number;
  /**
   * Насколько покрытие вязнет под колесом: доля нагрузки, уходящая в
   * прокапывание колеи. На траве это главная причина, по которой машина едет
   * медленно, — и она не имеет отношения к сцеплению.
   *
   * Число здесь нельзя ставить наугад: вместе с `roll` оно должно оставаться
   * заметно меньше, чем `grip`, помноженное на то, что держит скользящая шина.
   * Иначе получается ловушка — сколько ни дай газу, сопротивление грунта больше
   * силы, которую колесо способно передать, и машина только зарывается.
   */
  dig: number;
  /**
   * Вспашка: сопротивление, растущее с квадратом скорости, в тех же единицах,
   * что и лобовое сопротивление кузова.
   *
   * Держать скорость на грунте обязано именно оно, а не `dig`. Разница не в
   * числах, а в том, что бывает на нуле: постоянное сопротивление одинаково
   * велико и на ста километрах в час, и на месте, поэтому, задрав его до
   * заметного на скорости, получаешь капкан — тронуться уже нельзя. Вспашка же
   * на месте не стоит ничего и потому режет верхнюю скорость, не отнимая
   * способности выехать.
   */
  plow: number;
  /** Насколько покрытие шумит под колесом: 1 — асфальт (см. звук). */
  noise: number;
}

export const SURFACES: Record<SurfaceKind, Surface> = {
  asphalt: { grip: 1, keeps: 1, roll: 0.013, dig: 0, plow: 0, noise: 1 },
  gravel: { grip: 0.62, keeps: 0.15, roll: 0.03, dig: 0.035, plow: 3.4, noise: 1.6 },
  grass: { grip: 0.42, keeps: 0, roll: 0.05, dig: 0.055, plow: 19, noise: 0.55 },
};

/**
 * Что под точкой: не одно покрытие, а переход между двумя.
 *
 * Границы размыты не для красоты. Кромка асфальта в жизни не нож, а полметра
 * выкрошенного края, и скачок сцепления в одном сантиметре дал бы не
 * правдоподобность, а дребезг на границе: колесо на кромке щёлкало бы между
 * асфальтом и гравием каждый шаг физики.
 */
export interface SurfaceMix {
  /** Покрытие, которого здесь больше. */
  kind: SurfaceKind;
  /** Соседнее покрытие, к которому идёт переход. */
  next: SurfaceKind;
  /** Доля соседнего: 0 — чистое `kind`, 1 — чистое `next`. */
  blend: number;
}

/** Смесь двух покрытий как одно: по нему и считается пятно контакта. */
export function blendSurface(from: Surface, to: Surface, blend: number): Surface {
  const t = Math.max(0, Math.min(1, blend));
  const mix = (a: number, b: number): number => a + (b - a) * t;
  return {
    grip: mix(from.grip, to.grip),
    keeps: mix(from.keeps, to.keeps),
    roll: mix(from.roll, to.roll),
    dig: mix(from.dig, to.dig),
    plow: mix(from.plow, to.plow),
    noise: mix(from.noise, to.noise),
  };
}

/** Смесь под точкой как одно покрытие: короткая дорога от запроса к числам. */
export function surfaceOf(mix: SurfaceMix): Surface {
  return blendSurface(SURFACES[mix.kind], SURFACES[mix.next], mix.blend);
}

/** Какое покрытие тут главное: им подписывают колесо в приборах, звуке и пыли. */
export function surfaceKindOf(mix: SurfaceMix): SurfaceKind {
  return mix.blend > 0.5 ? mix.next : mix.kind;
}
